package api

import (
	"errors"
	"net/http"
	"regexp"
	"strings"
	"unicode"
	"unicode/utf8"

	"infrapilot/internal/store"
)

const maxProjectNameRunes = 100

// idShape covers every id the system stores: cuids generated by the store and
// legacy Node/Prisma cuids (lowercase alphanumerics), with headroom.
var idShape = regexp.MustCompile(`^[A-Za-z0-9_-]{1,64}$`)

// pathID returns the "id" path value and whether it can be a stored id. Every
// handler that reads an {id} path value MUST use this (Tasks 8-12 included),
// never r.PathValue directly: a NUL byte or invalid UTF-8 makes Postgres reject
// the parameter and the request would answer 500 instead of the route's usual
// 404. When ok is false, answer exactly as for a missing id.
func pathID(r *http.Request) (string, bool) {
	id := r.PathValue("id")
	return id, idShape.MatchString(id)
}

// validProjectName requires 2 to 100 runes and no control characters (a NUL
// byte would pass the length check and make Postgres fail with a 500).
func validProjectName(name string) bool {
	n := utf8.RuneCountInString(name)
	if n < 2 || n > maxProjectNameRunes || !utf8.ValidString(name) {
		return false
	}
	for _, r := range name {
		if unicode.IsControl(r) {
			return false
		}
	}
	return true
}

// cleanName trims surrounding white space (Unicode, as the UI does) and
// validates the result. Callers store the returned name, never the raw input.
func cleanName(raw string) (string, bool) {
	name := strings.TrimSpace(raw)
	return name, validProjectName(name)
}

func (s *Server) createProject(w http.ResponseWriter, r *http.Request) {
	var body struct {
		Name string `json:"name"`
	}
	if err := decodeJSON(w, r, &body); err != nil {
		writeDecodeError(w, err, "invalid_request")
		return
	}
	name, ok := cleanName(body.Name)
	if !ok {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	p, err := s.Store.CreateProject(r.Context(), name, userID(r))
	if errors.Is(err, store.ErrNoSuchUser) {
		// A validly signed token for a user that no longer exists.
		writeError(w, http.StatusUnauthorized, "unauthorized")
		return
	}
	if err != nil {
		s.internalError(w, r, err)
		return
	}
	writeJSON(w, http.StatusOK, p)
}

func (s *Server) listProjects(w http.ResponseWriter, r *http.Request) {
	ps, err := s.Store.ListProjects(r.Context(), userID(r))
	if err != nil {
		s.internalError(w, r, err)
		return
	}
	writeJSON(w, http.StatusOK, ps)
}

// getProject answers 404 for a missing project and for one owned by someone
// else, so ids cannot be probed.
func (s *Server) getProject(w http.ResponseWriter, r *http.Request) {
	id, ok := pathID(r)
	if !ok {
		writeError(w, http.StatusNotFound, "Project not found")
		return
	}
	p, err := s.Store.GetProjectForOwner(r.Context(), id, userID(r))
	if errors.Is(err, store.ErrNotFound) {
		writeError(w, http.StatusNotFound, "Project not found")
		return
	}
	if err != nil {
		s.internalError(w, r, err)
		return
	}
	writeJSON(w, http.StatusOK, p)
}
